<?php

namespace App\Support\Settings;

/**
 * Which runtime reads each settings key — Proposal 149 §183.
 *
 * `resources/settings/coverage.json` is generated by the settings sweep from
 * source evidence, not hand-written: each bucket is a claim about code, and a
 * hand-maintained claim about code is wrong the first time the code moves. This
 * class is the only reader of that file, so the page and any future report agree
 * on the vocabulary.
 *
 * WHY A PAGE AT ALL
 *
 * `/admin/settings` renders the whole catalogue — several hundred controls. Only a
 * fraction of them change behaviour in this runtime. The rest are one of eight
 * other things, and an administrator cannot tell which is which from the form.
 * That is the failure §178.1 names: a rendered control implies a reader. The
 * honest fix is not to delete the WordPress rows — most of the catalogue is the
 * ported surface and deleting them would delete the parity map — but to state the
 * coverage where an operator can see it.
 *
 * (The counts live in the artefact, not in this docblock. A number written here
 * was wrong by one within a release the last time it was tried.)
 *
 * The distinction that matters most is `unenforced`. A security control that is
 * writable and read by nothing records an intention while changing no
 * behaviour, so an operator who sets it believes they have hardened a runtime
 * they have not touched. That class is surfaced first, not buried in a table.
 *
 * `wordpress-dynamic` exists because a literal scan cannot see a key the plugin
 * builds (`$slug . '_safety_buffer'`). Without it those keys read as "defined by
 * no source", which is a false statement about code that plainly exists.
 *
 * WHAT THIS CLASS WILL NOT DO
 *
 * It runs no query and reads no setting. The buckets describe *code*, not a
 * deployment, so the answer is the same on every estate and costs nothing to
 * render. A coverage page that needed a database read would be the one page in
 * the panel that fails when the database is the problem.
 *
 * @see \App\Support\SettingsSchema::fields()
 * @see \App\Support\Settings\InapplicableSettings
 * @see \App\Support\Settings\UnimplementedSettings
 */
final class SettingsCoverage
{
    /**
     * Bucket order for display: what is wrong first, then what is neutral.
     *
     * Ordered by the decision an operator makes on seeing it, not by count. A
     * count-ordered list puts the 469 WordPress rows first and the 26 unenforced
     * security controls below the fold.
     */
    public const ORDER = array(
        'unenforced',
        'unenforced-operator',
        'unclassified',
        'stale',
        'reported',
        'enforced',
        'inapplicable',
        'inert',
        'wordpress',
        'wordpress-dynamic',
    );

    /**
     * Display labels. The bucket ids are the artefact's vocabulary and stay
     * stable; only these are presentation.
     */
    public const LABELS = array(
        'unenforced' => 'Writable here, enforced nowhere',
        'unenforced-operator' => 'Operator control, enforced nowhere',
        'unclassified' => 'No reader found',
        'stale' => 'Not defined by any source',
        'reported' => 'Graded, not enforced',
        'enforced' => 'Enforced here',
        'inapplicable' => 'Not applicable here',
        'inert' => 'Not built here',
        'wordpress' => 'WordPress settings',
        'wordpress-dynamic' => 'WordPress settings (built by slug)',
    );

    /**
     * Decoded artefact, cached for the request.
     *
     * @var array<string, mixed>|null
     */
    private static ?array $document = null;

    /**
     * Absolute path to the generated coverage map.
     */
    public static function path(): string
    {
        return resource_path('settings/coverage.json');
    }

    /**
     * The decoded artefact, or an empty shape when it is missing or malformed.
     *
     * A missing file is a build problem, not a runtime one: the page still
     * renders and says so, because a coverage report that throws is worse than
     * one that admits it has nothing to report.
     *
     * @return array{buckets: array<string, string>, fields: list<array{key: string, bucket: string, reason: string}>}
     */
    public static function document(): array
    {
        if (null !== self::$document) {
            return self::$document;
        }

        $empty = array('buckets' => array(), 'fields' => array());
        $path = self::path();

        if (! is_file($path)) {
            self::$document = $empty;

            return self::$document;
        }

        $decoded = json_decode((string) file_get_contents($path), true);

        if (! is_array($decoded) || ! isset($decoded['fields']) || ! is_array($decoded['fields'])) {
            self::$document = $empty;

            return self::$document;
        }

        self::$document = array(
            'buckets' => is_array($decoded['buckets'] ?? null) ? $decoded['buckets'] : array(),
            'fields' => array_values($decoded['fields']),
        );

        return self::$document;
    }

    /**
     * The bucket definitions, for the legend.
     *
     * @return array<string, string>
     */
    public static function bucketReasons(): array
    {
        return self::document()['buckets'];
    }

    /**
     * Every classified key.
     *
     * @return list<array{key: string, bucket: string, reason: string}>
     */
    public static function rows(): array
    {
        return self::document()['fields'];
    }

    public static function total(): int
    {
        return count(self::rows());
    }

    /**
     * Keys per bucket.
     *
     * @return array<string, int>
     */
    public static function counts(): array
    {
        $counts = array();

        foreach (self::rows() as $row) {
            $bucket = (string) ($row['bucket'] ?? '');
            $counts[ $bucket ] = ( $counts[ $bucket ] ?? 0 ) + 1;
        }

        return $counts;
    }

    /**
     * One bucket's keys, in artefact order.
     *
     * @return list<array{key: string, bucket: string, reason: string}>
     */
    public static function byBucket(string $bucket): array
    {
        return array_values(array_filter(
            self::rows(),
            static fn (array $row): bool => ($row['bucket'] ?? '') === $bucket
        ));
    }

    /**
     * The buckets present in the artefact, in display order.
     *
     * Buckets that the artefact defines but no key uses are dropped, and a
     * bucket that appears in the data but not in `ORDER` is appended rather than
     * silently lost — a generator that adds a bucket should make it to the page
     * without a second edit here.
     *
     * @return list<string>
     */
    public static function presentBuckets(): array
    {
        $counts = self::counts();
        $ordered = array();

        foreach (self::ORDER as $bucket) {
            if (($counts[ $bucket ] ?? 0) > 0) {
                $ordered[] = $bucket;
            }
        }

        foreach (array_keys($counts) as $bucket) {
            if (! in_array($bucket, $ordered, true) && $counts[ $bucket ] > 0) {
                $ordered[] = $bucket;
            }
        }

        return $ordered;
    }

    public static function label(string $bucket): string
    {
        return self::LABELS[ $bucket ] ?? ucfirst(str_replace('-', ' ', $bucket));
    }

    public static function reason(string $bucket): string
    {
        return self::bucketReasons()[ $bucket ] ?? '';
    }

    /**
     * Is this a bucket an operator can act on?
     *
     * `wordpress` and `enforced` are not problems, and neither are the two
     * declared buckets: they are the system working. The rest describe controls
     * whose relationship to behaviour is unclear, which is exactly the set worth
     * naming one key at a time.
     */
    public static function isProblem(string $bucket): bool
    {
        return in_array($bucket, array('unenforced', 'unenforced-operator', 'unclassified', 'stale', 'reported'), true);
    }

    /**
     * The buckets worth listing key by key, in display order.
     *
     * @return list<string>
     */
    public static function problemBuckets(): array
    {
        return array_values(array_filter(self::presentBuckets(), array(self::class, 'isProblem')));
    }
}
